package com.greenocean.backend.trust;
import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.transaction.annotation.Transactional;import java.util.*;
/** Default-off technical detectors inspect only bounded metadata/aggregates, never private narratives. */
@Service
public class IncidentSignals {
 private final JdbcTemplate db;private final TrustAuthority authority;private final boolean enabled;private final int threshold;
 public IncidentSignals(JdbcTemplate db,TrustAuthority authority,@Value("${greenocean.operations.signal-worker-enabled:false}")boolean enabled,@Value("${greenocean.operations.signal-threshold:3}")int threshold){this.db=db;this.authority=authority;this.enabled=enabled;if(threshold<1||threshold>1000)throw new IllegalArgumentException("Choose a bounded technical signal threshold1–1000");this.threshold=threshold;}
 @Scheduled(fixedDelayString="${greenocean.operations.signal-sweep-ms:30000}",initialDelayString="${greenocean.operations.signal-sweep-ms:30000}")@Transactional public void observe(){if(!enabled||!authority.enabled())return;
  signal("PLATFORM","EMAIL_OUTAGE","SEV2","email-transport-retries",db.queryForObject("SELECT count(*) FROM email_outbox WHERE status IN('FAILED','DEAD') AND attempts>=3 AND created_at>CURRENT_TIMESTAMP-INTERVAL '15 minutes'",Integer.class)>=threshold);
  signal("FINANCE","REFUND_DELAY","SEV2","overdue-unconfirmed-refunds",db.queryForObject("SELECT count(*) FROM clinic_refunds WHERE state IN('REFUND_ELIGIBLE','REFUND_REQUESTED','REFUND_PROCESSING','REFUND_FAILED','MANUAL_REVIEW_REQUIRED') AND initiate_by<CURRENT_TIMESTAMP",Integer.class)>=threshold);
  signal("LISTENER","STAFFING_GAP","SEV2","waiting-without-qualified-coverage",Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM listener_wait_queue q WHERE q.status IN('WAITING','OFFERED') AND NOT listener_queue_has_coverage(q.member_id,q.language))",Boolean.class)));
  signal("CLINIC","MEDIA_INTERRUPTION","SEV2","recent-technical-encounter-failures",db.queryForObject("SELECT count(*) FROM clinic_encounters WHERE state='TECHNICAL_FAILURE' AND ended_at>CURRENT_TIMESTAMP-INTERVAL '15 minutes'",Integer.class)>=threshold);
 }
 private void signal(String domain,String kind,String severity,String fixedReference,boolean condition){if(!condition)return;db.queryForList("SELECT pg_advisory_xact_lock(hashtextextended(?,0))","operational-signal:"+domain+":"+kind);if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM operation_incidents WHERE domain=? AND kind=? AND state NOT IN('RESOLVED','POST_INCIDENT_REVIEW','CLOSED'))",Boolean.class,domain,kind)))return;UUID id=UUID.randomUUID();String reference="SIGNAL:"+fixedReference;db.update("INSERT INTO operation_incidents(id,domain,kind,severity,evidence_reference,dedup_key) VALUES(?,?,?,?,?,?)",id,domain,kind,severity,reference,UUID.randomUUID());db.update("INSERT INTO operation_incident_events(incident_id,revision,to_state,evidence_reference) VALUES(?,1,'DETECTED',?)",id,reference);}
}
